"""Nominally cover autogenerated files.

AUTOGENERATED by https://github.com/biobuddies/measles
"""

from importlib import import_module
from importlib.metadata import distributions

from pytest import skip


def test_boilerplate():
    pass


def test_arrangement_imports_installed_package() -> None:
    """With the wheel installed, `pytest --import-mode=importlib` imports it, not the source."""
    installed = [
        distribution
        for distribution in distributions(name='measles')
        if distribution.read_text('INSTALLER')
    ]
    if not installed:
        skip('measles is not installed')
    location = str(installed[0].locate_file('measles/__init__.py'))
    assert import_module('measles').__file__ == location
